/**
 * DACI Decision Doc — tool-local actions.
 *
 * Category: Decision Frameworks (squad S13, Wave 2 — decision-CRUD tools)
 * Tool:     Driver / Approver / Contributors / Informed
 *
 * Agent surface: tool.daci.*
 * Backing CRUD : workspace.daci_decision.* (auto-generated by
 *                defineCrudActions in src/lib/actions/workspace/index.ts).
 *
 * ─── CRUD-BACKED tool pattern (vs the calculator pattern) ────────────
 * Unlike WSJF / RICE / ICE (which are scoring calculators), DACI is a
 * pure record-keeping entity. Generic create / list / update / delete
 * already exist via the auto-generated workspace.daci_decision.* surface,
 * so this file only adds VERBS THE AGENT WANTS TO SPEAK in DACI's domain
 * vocabulary — things the generic CRUD surface can't express without the
 * agent constructing a full patch payload:
 *
 *   1. list_state        — read all decisions + summary stats (byStatus,
 *                          total). Lets the agent plan ("how many open?")
 *                          without paging through every record.
 *   2. set_status        — convenience over a workspace.daci_decision.update
 *                          patch. Status is the single most-mutated field
 *                          in a decision's lifecycle (open → decided →
 *                          implemented), and the agent shouldn't have to
 *                          marshal a {patch: {status: ...}} object.
 *   3. add_contributor   — idempotent append to the contributors[] role
 *                          list. Saves the agent from reading-then-merging
 *                          and avoids the contributor-list overwrite bug
 *                          that a naive `update` patch would cause.
 *   4. add_informed      — idempotent append to the informed[] role list.
 *
 * `add_contributor` and `add_informed` are additive operations on a
 * specific decision; they read the current row first, append if not
 * already present, then upsert. Marked `requiresConfirmation: false`
 * because they don't destroy data (just add a name to a role list) and
 * the natural agent phrasing — "add Bob to the contributors for the
 * pricing decision" — would be unbearable to confirm individually.
 *
 * ─── ID NAMING ───────────────────────────────────────────────────────
 * Namespace is `tool.daci` (no hyphens). The auto-generated CRUD
 * surface uses `workspace.daci_decision` with an underscore between
 * "daci" and "decision" (an entity name convention), but the tool-id
 * is the user-facing tool slug from the URL (/daci) — kept tight.
 * ─────────────────────────────────────────────────────────────────────
 */

import { z } from "zod";
import { registry } from "../registry";
import { useWorkspaceStore } from "@/lib/stores/workspace-store";
import { serverListEntities, serverGetEntity, serverUpsertEntity } from "../server-store";
import type { DACIDecision } from "@/lib/stores/workspace-types";

/** Server-side entity kind. Matches kindFromToolId("workspace.daci_decision")
 *  used by the auto-generated CRUD in src/lib/actions/workspace/index.ts,
 *  so reads/writes here line up byte-for-byte with the generic surface.
 *  Browser-side sync registers the same "workspace:daciDecision" kind, so
 *  MCP writes round-trip into the browser store. */
const KIND_DACI = "workspace:daciDecision";

/** Closed enum of valid DACI lifecycle statuses. Matches the literal
 *  union in workspace-types.ts:DACIDecision.status verbatim — Zod will
 *  reject anything else at the boundary. */
const STATUSES = ["open", "decided", "implemented", "revisit"] as const;
const StatusSchema = z.enum(STATUSES);

const ws = () => useWorkspaceStore.getState();

// ──────── tool.daci.list_state ────────
// Snapshot + summary stats. The agent's most common opening question
// for a decision tool is "what's the state of decisions?" — returning
// the items array AND a byStatus breakdown in one round-trip avoids a
// follow-up reduce on the agent's end.
registry.register({
  id: "tool.daci.list_state",
  toolId: "tool.daci",
  name: "list_state",
  category: "read",
  description:
    "List all DACI decisions in the workspace with a summary breakdown by status. Returns {total, byStatus: {open, decided, implemented, revisit}, items: DACIDecision[]}.",
  paramsSchema: z.object({}),
  handler: async () => {
    const items = ws().daciDecisions ?? [];
    return summarize(items);
  },
  mcpHandler: async (_params, ctx) => {
    const items = await serverListEntities<DACIDecision>(ctx.userId, KIND_DACI);
    return summarize(items);
  },
});

/** Build the {total, byStatus, items} response shape. Kept as a single
 *  helper so the browser-path and MCP-path responses are guaranteed
 *  identical — drift here would mean an agent gets different shapes
 *  depending on whether it's invoked from chat or over MCP. */
function summarize(items: DACIDecision[]) {
  // Initialise every status key so the agent can index byStatus.open
  // without an existence check, even when the workspace is empty.
  const byStatus: Record<DACIDecision["status"], number> = {
    open: 0,
    decided: 0,
    implemented: 0,
    revisit: 0,
  };
  for (const d of items) {
    // Defensive: a hand-crafted entity with an out-of-enum status would
    // otherwise NaN the bucket. Skip silently — the items array still
    // carries the row so the agent can spot it if needed.
    if (d.status in byStatus) byStatus[d.status] += 1;
  }
  return { total: items.length, byStatus, items };
}

// ──────── tool.daci.set_status ────────
// Convenience over workspace.daci_decision.update. The status field is
// the single most-mutated property in a decision's lifecycle (open →
// decided → implemented; revisit when reopened), and the generic
// update surface requires marshalling a full {patch: {status: ...}}
// payload. Returns {updated: boolean} so the agent can detect missing-id
// without throwing.
registry.register({
  id: "tool.daci.set_status",
  toolId: "tool.daci",
  name: "set_status",
  category: "write",
  description:
    "Update the status of an existing DACI decision (open | decided | implemented | revisit). Returns {updated: false} when the id is unknown.",
  paramsSchema: z.object({
    id: z.string(),
    status: StatusSchema,
  }),
  handler: async (params) => {
    const items = ws().daciDecisions ?? [];
    const current = items.find((d) => d.id === params.id);
    if (!current) return { updated: false };
    ws().upsertDACIDecision({ ...current, status: params.status });
    return { updated: true };
  },
  mcpHandler: async (params, ctx) => {
    const current = await serverGetEntity<DACIDecision>(ctx.userId, KIND_DACI, params.id);
    if (!current) return { updated: false };
    await serverUpsertEntity<DACIDecision>(ctx.userId, KIND_DACI, {
      ...current,
      status: params.status,
    });
    return { updated: true };
  },
});

// ──────── tool.daci.add_contributor ────────
// Idempotent append to contributors[]. Read-modify-write through the
// store / server so a concurrent agent call that already added the same
// name won't produce duplicate entries. Returns {added: boolean} —
// false when the name was already present OR the decision is missing.
// (The two cases are distinguishable by reading {found} too — but the
// agent's natural usage is fire-and-forget, so we keep the surface
// minimal and let the agent re-list if it cares.)
registry.register({
  id: "tool.daci.add_contributor",
  toolId: "tool.daci",
  name: "add_contributor",
  category: "write",
  requiresConfirmation: false,
  description:
    "Append a name to the contributors[] of an existing DACI decision. Idempotent — skips if the name is already present. Returns {added: false} when the id is unknown OR the name was already there.",
  paramsSchema: z.object({
    id: z.string(),
    contributor: z.string().min(1).max(120),
  }),
  handler: async (params) => {
    const items = ws().daciDecisions ?? [];
    const current = items.find((d) => d.id === params.id);
    if (!current) return { added: false };
    const existing = current.contributors ?? [];
    if (existing.includes(params.contributor)) return { added: false };
    ws().upsertDACIDecision({
      ...current,
      contributors: [...existing, params.contributor],
    });
    return { added: true };
  },
  mcpHandler: async (params, ctx) => {
    const current = await serverGetEntity<DACIDecision>(ctx.userId, KIND_DACI, params.id);
    if (!current) return { added: false };
    const existing = current.contributors ?? [];
    if (existing.includes(params.contributor)) return { added: false };
    await serverUpsertEntity<DACIDecision>(ctx.userId, KIND_DACI, {
      ...current,
      contributors: [...existing, params.contributor],
    });
    return { added: true };
  },
});

// ──────── tool.daci.add_informed ────────
// Symmetric to add_contributor — same idempotency semantics, same
// minimal {added: boolean} surface. The informed list is typically
// stakeholders who need to know the outcome but aren't part of the
// decision-making process.
registry.register({
  id: "tool.daci.add_informed",
  toolId: "tool.daci",
  name: "add_informed",
  category: "write",
  requiresConfirmation: false,
  description:
    "Append a name to the informed[] of an existing DACI decision. Idempotent — skips if the name is already present. Returns {added: false} when the id is unknown OR the name was already there.",
  paramsSchema: z.object({
    id: z.string(),
    informed: z.string().min(1).max(120),
  }),
  handler: async (params) => {
    const items = ws().daciDecisions ?? [];
    const current = items.find((d) => d.id === params.id);
    if (!current) return { added: false };
    const existing = current.informed ?? [];
    if (existing.includes(params.informed)) return { added: false };
    ws().upsertDACIDecision({
      ...current,
      informed: [...existing, params.informed],
    });
    return { added: true };
  },
  mcpHandler: async (params, ctx) => {
    const current = await serverGetEntity<DACIDecision>(ctx.userId, KIND_DACI, params.id);
    if (!current) return { added: false };
    const existing = current.informed ?? [];
    if (existing.includes(params.informed)) return { added: false };
    await serverUpsertEntity<DACIDecision>(ctx.userId, KIND_DACI, {
      ...current,
      informed: [...existing, params.informed],
    });
    return { added: true };
  },
});
